public class ExtendedAccessChecker {
    static String classifyAccess(String fieldModifier, String accessorContext) { if (accessorContext.equals("SAME_CLASS") || fieldModifier.equals("public")) return "ALLOWED"; if (fieldModifier.equals("private")) return "DENIED"; if (accessorContext.equals("SAME_PACKAGE")) return (fieldModifier.equals("default") || fieldModifier.equals("protected")) ? "ALLOWED" : "DENIED"; if (fieldModifier.equals("protected")) { if (accessorContext.equals("SUBCLASS_DIFFERENT_PACKAGE_OWN_TYPE")) return "ALLOWED"; if (accessorContext.equals("SUBCLASS_DIFFERENT_PACKAGE_PARENT_TYPE")) return "DENIED"; } return "DENIED"; }
    static String firstDeniedAttempt(String[][] attempts) { for (int i = 0; i < attempts.length; i++) if (classifyAccess(attempts[i][0], attempts[i][1]).equals("DENIED")) return attempts[i][0] + " via " + attempts[i][1] + " (attempt #" + (i + 1) + ")"; return "None Denied"; }
    public static void main(String[] args) { String[][] attempts1 = {{"public", "SUBCLASS_DIFFERENT_PACKAGE_PARENT_TYPE"}, {"protected", "SUBCLASS_DIFFERENT_PACKAGE_PARENT_TYPE"}, {"protected", "SUBCLASS_DIFFERENT_PACKAGE_OWN_TYPE"}}; String[][] attempts2 = {{"public", "SUBCLASS_DIFFERENT_PACKAGE_OWN_TYPE"}, {"protected", "SUBCLASS_DIFFERENT_PACKAGE_OWN_TYPE"}}; System.out.println(firstDeniedAttempt(attempts1)); System.out.println(firstDeniedAttempt(attempts2)); }
}